import os, re, sys
import xml.dom.minidom as minidom

W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
DOC_PATH = "unpacked/word/document.xml"

# Informational: list files under word/ to confirm where body content lives
for root, dirs, files in os.walk("unpacked/word"):
    for f in sorted(files):
        print("word file:", os.path.relpath(os.path.join(root, f), "unpacked/word"))

dom = minidom.parse(DOC_PATH)

def para_text(p):
    parts = []
    for t in p.getElementsByTagNameNS(W_NS, "t"):
        if t.firstChild:
            parts.append(t.firstChild.data)
    return "".join(parts)

ALL_CAPS_RE = re.compile(r"^[A-Z0-9 .,&'()%:/\u2019-]+$")

def looks_like_headline(text):
    s = text.strip()
    if not s or not any(c.isupper() for c in s):
        return False
    return bool(ALL_CAPS_RE.match(s))

headline_count = 0
run_count = 0

for p in dom.getElementsByTagNameNS(W_NS, "p"):
    text = para_text(p)
    if not looks_like_headline(text):
        continue
    headline_count += 1
    print("HEADLINE:", repr(text))
    for r in p.getElementsByTagNameNS(W_NS, "r"):
        rprs = r.getElementsByTagNameNS(W_NS, "rPr")
        if rprs:
            rpr = rprs[0]
        else:
            rpr = dom.createElementNS(W_NS, "w:rPr")
            r.insertBefore(rpr, r.firstChild)
        us = rpr.getElementsByTagNameNS(W_NS, "u")
        if us:
            us[0].setAttributeNS(W_NS, "w:val", "single")
        else:
            u = dom.createElementNS(W_NS, "w:u")
            u.setAttributeNS(W_NS, "w:val", "single")
            rpr.appendChild(u)
            run_count += 1

with open(DOC_PATH, "w", encoding="utf-8") as f:
    f.write('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n')
    f.write(dom.documentElement.toxml())

print("headlines underlined:", headline_count)
print("runs updated:", run_count)

